contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function configured() public view returns (bool) { return true; }

    function run(bool enable, uint256 v1, uint256 v2) public payable {
        c.setEnforcement(enable);
        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; }
        catch { reverted = true; }
        bool expectRevert = enable &&
            !(v1 == v2 || (v1 == 1 && v2 == 0) || (v1 == 0 && v2 == 1));
        assert(reverted == expectRevert);
    }

    receive() external payable {}
}

