contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public payable {
        // disable enforcement for this contract's address
        c.setEnforcement(false);
        bool revertedWhenOff;
        bool ok1;
        try c.enforceTolerance(v1, v2) { revertedWhenOff = false; ok1 = true; } catch { revertedWhenOff = true; ok1 = true; }
        require(ok1);

        // enable enforcement for this contract's address
        c.setEnforcement(true);
        bool revertedWhenOn;
        bool ok2;
        try c.enforceTolerance(v1, v2) { revertedWhenOn = false; ok2 = true; } catch { revertedWhenOn = true; ok2 = true; }
        require(ok2);

        // disable again; extreme values must also pass
        c.setEnforcement(false);
        bool revertedOffBig;
        bool ok3;
        try c.enforceTolerance(v1 + 10**30, 0) { revertedOffBig = false; ok3 = true; } catch { revertedOffBig = true; ok3 = true; }
        require(ok3);

        assert(!revertedWhenOff && !revertedOffBig && revertedWhenOn);
    }

    receive() external payable {}
}

