contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v1, uint256 v2) public {
        c.setEnforcement(true);
        bool reverted;
        // enforceTolerance consults Configurable(msg.sender).configured();
        // this test contract does not implement configured() as a declared
        // function, so the fallback below returns false, meaning enforcement
        // is inactive and the call must never revert.
        try c.enforceTolerance(v1, v2) { reverted = false; }
        catch { reverted = true; }
        assert(!reverted);
    }
    fallback() external {
        // return false for configured() selector, empty otherwise
        assembly {
            if eq(calldataload(0), 0x24a52c52) {
                mstore(0, 0)
                return(0, 32)
            }
            return(0, 0)
        }
    }
    receive() external payable {}
}

contract InvMutTest {
