    function run(address other, bool v) public {
        bool beforeSelf = c.enforceLimitsActive(address(this));
        bool beforeOther = c.enforceLimitsActive(other);
        c.setEnforcement(v);
        bool afterSelf = c.enforceLimitsActive(address(this));
        bool afterOther = c.enforceLimitsActive(other);
        assert(afterSelf == v && afterOther == beforeOther && (v == beforeSelf || true) && !(afterSelf == beforeSelf && v != beforeSelf));
    }
    receive() external payable {}
}

