contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a, address b, bool flag) public {
        require(a != address(0) && b != address(0) && a != b && a != address(this) && b != address(this));
        address[] memory gs = new address[](2);
        gs[0] = a;
        gs[1] = b;
        bool[] memory vs = new bool[](2);
        vs[0] = flag;
        vs[1] = !flag;
        c.setGoverned(gs, vs);
        bool gA = c.governed(a);
        bool gB = c.governed(b);
        bool r1;
        try c.assertGovernanceApproved(a, address(this), false) { r1 = false; } catch { r1 = true; }
        c.endConfiguration();
        bool r2;
        try c.setGoverned(gs, vs) { r2 = false; } catch { r2 = true; }
        assert(gA == flag && gB == (!flag) && r1 && r2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        require(address(c).code.length > 0);
        require(!c.configured());

        (uint256 a0, uint256 u0, address asset0, bool b0) = c.flashGovernanceConfig();
        require(a0 == 0 && asset0 == address(0), "dirty");

        // msg.sender is not the DAO, but configured() is false so the
        // onlySuccessfulProposal gate passes for anyone.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        (uint256 a1, uint256 u1, address asset1, bool b1) = c.flashGovernanceConfig();
        assert(a1 == amount && u1 == unlockTime && asset1 == asset && b1 == assetBurnable);
    }
}

contract InvMutTest {
