    function run(uint256 v1, uint256 v2) public {
        require(address(c).code.length > 0);

        // Enforcement is off for this caller by default (enforceLimitsActive[msg.sender] == false),
        // so enforceTolerance must short-circuit and succeed for ANY pair of values,
        // even ones that would fail the tolerance check.
        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }

        assert(!reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool b) public {
        require(address(c).code.length > 0);

        // default state should be off
        bool before = c.enforceLimitsActive(address(this));

        c.setEnforcement(b);
        bool afterSet = c.enforceLimitsActive(address(this));

        c.setEnforcement(!b);
        bool afterToggle = c.enforceLimitsActive(address(this));

        assert(!before && afterSet == b && afterToggle == !b);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1) public {
        require(address(c).code.length > 0);
        require(v1 > 0);

        c.setEnforcement(true);

        // v2 = 2*v1 => (v2 - v1)*100 = 100*v1 >= changeTolerance*v1 (changeTolerance < 100)
        // so the tolerance check must revert (given msg.sender is Configurable with configured() true).
        bool reverted1;
        try c.enforceTolerance(v1, 2 * v1) { reverted1 = false; } catch { reverted1 = true; }

        c.setEnforcement(false);

        // With enforcement off it must not revert.
        bool reverted2;
        try c.enforceTolerance(v1, 2 * v1) { reverted2 = false; } catch { reverted2 = true; }

        assert(reverted1 && !reverted2);
    }

    receive() external payable {}
}

