contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, bool enforce, uint8 tol) public payable {
        require(v2 > 0 && v2 <= v1 && v1 < 1e30);
        require(tol < 100);

        // configure tolerance and toggle enforcement for this contract (msg.sender of all calls)
        c.configureSecurityParameters(10, 1000, tol);
        c.setEnforcement(enforce);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // expected: revert only if enforcement is active AND change exceeds tolerance percent
        bool exceedsTolerance = ((v1 - v2) * 100) >= (uint256(tol) * v1);
        bool expectedRevert = enforce && exceedsTolerance;

        assert(reverted == expectedRevert);
    }

    receive() external payable {}
}

