contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, address user, address asset) public {
        require(target != address(0) && user != address(0));
        // read the (empty) pending decision before the call
        (uint256 amtBefore, uint256 unlockBefore, , ) = c.pendingFlashDecision(target, user);
        // the deciding call: withdraw an asset that was never deposited
        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // read the pending decision after the call
        (uint256 amtAfter, uint256 unlockAfter, , ) = c.pendingFlashDecision(target, user);
        assert(
            reverted &&
            amtBefore == 0 && unlockBefore == 0 &&
            amtAfter == 0 && unlockAfter == 0
        );
    }
    receive() external payable {}
}

