            enforcingOffReverted = false;
        } catch {
            enforcingOffReverted = true;
        }

        // Turn enforcement ON for this caller via the public setter.
        c.setEnforcement(true);

        bool enforcingOnReverted;
        try c.enforceTolerance(v1, v2) {
            enforcingOnReverted = false;
        } catch {
            enforcingOnReverted = true;
        }

        // Turning it back OFF must make the check pass again.
        c.setEnforcement(false);

        bool offAgainReverted;
        try c.enforceTolerance(v1, v2) {
            offAgainReverted = false;
        } catch {
            offAgainReverted = true;
        }

        assert(!enforcingOffReverted && enforcingOnReverted && !offAgainReverted);
    }

    receive() external payable {}
}

