contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Makes Configurable(msg.sender).configured() return true so the
    // tolerance check is actually evaluated inside enforceTolerance.
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(true);
    }

    function run(uint256 v, uint8 maxChange, uint256 epochSize, uint8 tolerance) public {
        require(v > 0);
        require(tolerance > 0 && tolerance < 100);

        // configured == false, so onlySuccessfulProposal passes for this caller.
        c.configureSecurityParameters(maxChange, epochSize, tolerance);
        c.setEnforcement(true);

        bool reverted;
        try c.enforceTolerance(v, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Equal nonzero values differ by 0, and 0 < tolerance * v holds for
        // tolerance > 0, v > 0: the check must never revert.
        assert(!reverted);
    }

    receive() external payable {}
}

